CREATE TRIGGER categories_insert BEFORE INSERT ON categories BEGIN
 SELECT RAISE(ABORT, 'category_cycle') WHERE NEW.parent_id=NEW.id OR EXISTS (
 WITH RECURSIVE ancestors(id,parent_id) AS (
 SELECT id,parent_id FROM categories WHERE id=NEW.parent_id
 UNION SELECT c.id,c.parent_id FROM categories c JOIN ancestors a ON c.id=a.parent_id
 ) SELECT 1 FROM ancestors WHERE id=NEW.id);
 SELECT RAISE(ABORT, 'category_depth') WHERE (
 WITH RECURSIVE ancestors(id,parent_id) AS (
 SELECT id,parent_id FROM categories WHERE id=NEW.parent_id
 UNION ALL SELECT c.id,c.parent_id FROM categories c JOIN ancestors a ON c.id=a.parent_id
 ) SELECT count(*) FROM ancestors
 ) + (
 WITH RECURSIVE descendants(id,depth) AS (
 SELECT NEW.id,1 UNION ALL SELECT c.id,d.depth+1 FROM categories c JOIN descendants d ON c.parent_id=d.id
 ) SELECT max(depth) FROM descendants
 ) > 3;
END;

